// Press sequence: start the turret, wait for speed, then watch the force
CASE Step OF
    0: // idle
        Compressing := FALSE;
        Turret_Run := FALSE;
        IF Cmd_Start AND GuardsOK THEN Step := 10; END_IF;

    10: // start the turret
        Turret_Run := TRUE;
        IF Turret_AtSpeed THEN Step := 20; END_IF;
        IF Cmd_Stop OR NOT GuardsOK THEN Step := 40; END_IF;

    20: // producing
        Compressing := TRUE;
        IF Force_Out_Of_Band THEN Step := 30; END_IF;
        IF Cmd_Stop OR NOT GuardsOK THEN Step := 40; END_IF;

    30: // force out of band: reject until it recovers
        Reject_All := TRUE;
        IF NOT Force_Out_Of_Band THEN
            Reject_All := FALSE;
            Step := 20;
        END_IF;
        IF Cmd_Stop OR NOT GuardsOK THEN Step := 40; END_IF;

    40: // stopping
        Compressing := FALSE;
        Reject_All := FALSE;
        Turret_Run := FALSE;
        IF Turret_Stopped THEN Step := 0; END_IF;
END_CASE;
